<template><view class="mobile-page"><text class="mobile-title">岗位分类审核</text><text v-if="message">{{ message }}</text><template v-if="!detail"><input v-model="search" placeholder="搜索岗位或企业" confirm-type="search" @confirm="load(1)"/><picker :range="statusLabels" @change="selectStatus"><view class="mobile-card">{{ statusLabels[statusIndex] }}</view></picker><button size="mini" :disabled="busy" @tap="load(1)">搜索 / 刷新</button><view v-for="item in list.items" :key="item.id" class="mobile-card"><text>{{ item.title }} · {{ item.company }}</text><text>{{ item.original_nature }} / {{ item.original_role }} · {{ states[item.status] || item.status }}</text><text v-if="item.error">{{ item.error }}</text><button size="mini" :disabled="busy" @tap="inspect(item.id)">查看 / 审核</button></view><text v-if="!busy && !list.items.length">当前没有匹配岗位。</text><view class="mobile-actions"><button size="mini" :disabled="busy||page<=1" @tap="load(page-1)">上一页</button><text>第 {{ page }} 页 · 共 {{ list.total || 0 }} 条</text><button size="mini" :disabled="busy||page*20>=list.total" @tap="load(page+1)">下一页</button></view></template><template v-else><button size="mini" :disabled="busy" @tap="detail=null">返回列表</button><view class="mobile-card"><text>{{ detail.posting.title }} · {{ detail.posting.company }}</text><text selectable>{{ detail.posting.description || '未采集到招聘正文' }}</text><text>建议：{{ proposal.reason || '尚无建议' }}</text><text v-for="(q,i) in proposal.quotes || []" :key="i" selectable>{{ q }}</text></view><button size="mini" :disabled="busy||detail.review.status==='approved'||(detail.review.status==='generating'&&!detail.review.retryable)" @tap="suggest">生成建议</button><picker :range="decisionLabels" :disabled="busy" @change="decision=decisions[Number($event.detail.value)]"><view class="mobile-card">{{ decisionLabels[decisions.indexOf(decision)] }}</view></picker><template v-if="decision==='classify'"><picker :range="list.natures||[]" :disabled="busy" @change="nature=list.natures[Number($event.detail.value)]"><view class="mobile-card">{{ nature || '选择工作性质' }}</view></picker><picker :range="list.roles||[]" :disabled="busy" @change="role=list.roles[Number($event.detail.value)]"><view class="mobile-card">{{ role || '选择岗位方向' }}</view></picker></template><textarea v-model="note" maxlength="1500" placeholder="填写审核说明" :disabled="busy"/><view class="mobile-actions"><button size="mini" :disabled="blocked||decision==='insufficient'" @tap="decide('approve')">通过</button><button size="mini" :disabled="blocked" @tap="decide('reject')">驳回</button><button size="mini" :disabled="blocked" @tap="decide('defer')">保留待确认</button></view><text>审核历史</text><text v-for="h in detail.history" :key="h.id" class="mobile-card">{{ h.at }} · {{ h.action }}</text></template></view></template>
<script setup>
import {ref,computed,onMounted} from 'vue'
import {request} from '../../utils/request'
const states={all:'全部状态',new:'待生成',generating:'生成中',pending:'待审核',failed:'生成失败',approved:'已通过',rejected:'已驳回',deferred:'保留待确认'}
const statusKeys=Object.keys(states),statusLabels=Object.values(states),decisions=['classify','non_it','insufficient'],decisionLabels=['归入已有分类','非 IT 招聘','证据不足']
const list=ref({items:[],total:0}),detail=ref(null),page=ref(1),search=ref(''),statusIndex=ref(0),busy=ref(false),message=ref(''),decision=ref('classify'),nature=ref(''),role=ref(''),note=ref('')
const blocked=computed(()=>busy.value||detail.value?.review?.status==='generating')
const proposal=computed(()=>{try{return JSON.parse(detail.value?.review?.suggestion_json||'{}')}catch{return {}}})
async function api(path,data){const r=await request({url:'/api/admin/classification'+path,method:data?'POST':'GET',data,timeout:90000});if(!r.success)throw new Error(r.message||'请求失败');return r.data}
async function run(work){if(busy.value)return;busy.value=true;message.value='';try{await work()}catch(e){message.value=e.message}finally{busy.value=false}}
async function fetchList(p){list.value=await api('/tasks?status='+statusKeys[statusIndex.value]+'&search='+encodeURIComponent(search.value.trim())+'&page='+p);page.value=p}
const load=p=>run(()=>fetchList(p))
function selectStatus(e){statusIndex.value=Number(e.detail.value);load(1)}
function show(d){detail.value=d;const r=d.review||{};const p=proposal.value;decision.value=r.status==='approved'?r.decision:(p.decision||'classify');nature.value=r.approved_nature||p.nature||'';role.value=r.approved_role||p.role||'';note.value=''}
const inspect=id=>run(async()=>show(await api('/tasks/'+encodeURIComponent(id))))
const path=()=>'/tasks/'+encodeURIComponent(detail.value.posting.id)
const suggest=()=>run(async()=>{show(await api(path()+'/suggest',{}));await fetchList(page.value)})
function decide(action){if(!note.value.trim()){message.value='请填写审核说明';return}if(action==='approve'&&decision.value==='classify'&&(!nature.value||!role.value)){message.value='请选择工作性质和岗位方向';return}return run(async()=>{show(await api(path()+'/decision',{action,version:detail.value.review?.version||0,decision:decision.value,nature:nature.value,role:role.value,note:note.value.trim()}));await fetchList(page.value);message.value='审核结果已保存'})}
onMounted(()=>load(1))
</script>
<style scoped src="../../styles/mobile-pages.css"></style>
